// Blog editor mounted inside the existing authenticated React workspace.
export function mountBlogEditor(root){
 let posts=[],current=null,csrf='',dirty=false,disposed=false,busy=false;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const blank=()=>({title:'',slug:'',description:'',seoTitle:'',category:'Practical guide',image:'',imageAlt:'',sections:[['','']]});
 const api=async(path,method='GET',body)=>{const response=await fetch('/api'+path,{method,headers:{...(body instanceof File?{'X-File-Name':encodeURIComponent(body.name)}:{'Content-Type':'application/json'}),'X-CSRF-Token':csrf},body:body===undefined?undefined:body instanceof File?body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed.');return data;};
 const alert=(message,error=false)=>{const el=root.querySelector('[role="status"]');if(el){el.textContent=message;el.style.color=error?'#b42318':'#146c43';}};
 function collect(){if(!current)return;for(const field of ['title','slug','description','seoTitle','category','image','imageAlt'])current[field]=root.querySelector(`[name="${field}"]`).value;current.sections=[...root.querySelectorAll('[data-section]')].map(el=>[el.querySelector('input').value,el.querySelector('textarea').value]);}
 function render(){
  if(disposed)return;
  root.innerHTML=`<style>.blog-admin-grid{display:grid;grid-template-columns:minmax(220px,1fr) minmax(0,2.6fr);gap:24px}.blog-editor-form label{display:grid;gap:7px;margin:16px 0;font-weight:600}.blog-editor-form input,.blog-editor-form textarea{width:100%;padding:12px;border:1px solid #cbd5e1;border-radius:7px;font:inherit;color:#142033;background:white;box-sizing:border-box}.blog-editor-form textarea{min-height:110px;line-height:1.65}.blog-editor-form small{color:#607086;font-weight:400}.blog-editor-form fieldset{border:1px solid #dbe2ec;border-radius:9px;margin:20px 0;padding:16px;min-width:0}.blog-editor-form legend{font-weight:700;padding:0 6px}.blog-editor-form .article-text{min-height:200px}.blog-post-button{display:block;width:100%;text-align:left;padding:14px;border:1px solid #e1e7ef;background:white;border-radius:8px;margin-bottom:10px;cursor:pointer;color:#142033}.blog-post-button[aria-current="true"]{border-color:#4266ee;background:#f2f5ff}.blog-post-button small{display:block;margin-top:7px;color:#607086}.blog-editor-actions{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.blog-featured-preview{max-height:180px;max-width:100%;object-fit:contain}#blog-editor-status{min-height:24px;margin:12px 0;white-space:pre-wrap}@media(max-width:900px){.blog-admin-grid{grid-template-columns:1fr}}</style>
  <div class="admin-panel-heading"><div><span class="admin-eyebrow">CONTENT & SEARCH</span><h1>Blogs</h1><p>Write, preview and publish articles. Saved drafts stay private until you publish.</p></div><button class="admin-button" data-action="new">Add blog</button></div>
  <div id="blog-editor-status" role="status" aria-live="polite"></div><div class="blog-admin-grid"><section class="admin-panel" style="padding:20px"><h2>All blogs <small>(${posts.length})</small></h2>${posts.map(p=>`<button class="blog-post-button" data-id="${esc(p.id)}" aria-current="${current?.id===p.id}"><strong>${esc(p.title)}</strong><small>${esc(p.status)}${p.hasUnpublishedChanges?' · unpublished changes':''}</small></button>`).join('')||'<p>No blogs yet. Start with Add blog.</p>'}<a href="/blogs" target="_blank" rel="noopener">View public blogs ↗</a></section><section class="admin-panel" style="padding:24px">${current?form():'<h2>Select an article</h2><p>Choose an existing blog to edit, or add a new one.</p>'}</section></div>`;
  root.querySelector('[data-action="new"]').onclick=()=>{if(!leave())return;current=blank();dirty=false;render();};
  for(const button of root.querySelectorAll('[data-id]'))button.onclick=()=>{if(!leave())return;current=structuredClone(posts.find(p=>p.id===button.dataset.id));dirty=false;render();};
  const f=root.querySelector('form');if(!f)return;
  f.oninput=()=>{dirty=true;};
  f.onsubmit=e=>{e.preventDefault();act(save);};
  root.querySelector('[data-action="add-section"]').onclick=()=>{collect();current.sections.push(['','']);dirty=true;render();};
  root.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{collect();if(current.sections.length===1){alert('Keep at least one article section.',true);return;}current.sections.splice(Number(el.dataset.remove),1);dirty=true;render();});
  root.querySelector('[name="upload"]').onchange=e=>act(async()=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8388608)throw Error('Choose a PNG, JPEG or WebP image up to 8 MB.');collect();const result=await api('/admin/media','POST',file);current.image=result.media.path;dirty=true;render();alert('Image uploaded. Add its description, then save the draft.');});
  root.querySelector('[data-action="preview"]').onclick=()=>{const win=window.open('about:blank','_blank');if(win)win.opener=null;act(async()=>{try{await save();if(win)win.location='/admin/blogs/preview/'+current.id;else alert('Draft saved. Allow pop-ups to open its preview.');}catch(error){win?.close();throw error;}});};
  for(const action of ['publish','unpublish'])root.querySelector(`[data-action="${action}"]`)?.addEventListener('click',async()=>{if(!await ask(action==='publish'?'Publish this saved article on the public website?':'Unpublish this article? It will leave the public blogs and sitemap.'))return;act(async()=>{if(action==='publish')await save();const data=await api('/admin/blogs/'+current.id+'/'+action,'POST',{version:current.version});current=data.post;dirty=false;await reload();render();alert(action==='publish'?'Published. The article is now live and included in the sitemap.':'Unpublished. The article is now a private draft.');});});
 }
 function form(){return `<form class="blog-editor-form"><h2>${current.id?'Edit blog':'New blog'}</h2><p>${current.status==='published'?'This article is live. Save draft changes, preview them, then publish to update the public version.':'This draft is private.'}</p>
 ${input('title','Blog title',180,true)}${input('slug','URL slug',100,true,current.id?'Existing URL is fixed to protect shared and indexed links.':'Use lowercase words and hyphens, e.g. website-planning-guide.',!!current.id)}<small>Public URL: /blogs/${esc(current.slug||'your-url-slug')}</small>${input('category','Category',60,true)}
 <label>Summary / meta description<textarea name="description" maxlength="320" required>${esc(current.description)}</textarea><small>A clear description for the blog card and search results. Around 150–160 characters is a useful starting point.</small></label>${input('seoTitle','SEO title',180,false,'Optional; defaults to the blog title. The website adds “| NEKSOFT”.')}
 <fieldset><legend>Featured image</legend>${current.image?`<img class="blog-featured-preview" src="${esc(current.image)}" alt="${esc(current.imageAlt)}">`:''}<label>Upload image<input name="upload" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP, up to 8 MB. Landscape images work best.</small></label>${input('image','Image path',500,false,'Use an uploaded /uploads/... image or an existing /images/... image. Leave empty for the existing illustration.')}${input('imageAlt','Image description (alt text)',240,!!current.image)}</fieldset>
 <h3>Article content</h3><p>Use a heading and body text for each section. Text is safely rendered without HTML; separate paragraphs with blank lines.</p>${current.sections.map(([h,p],i)=>`<fieldset data-section><legend>Section ${i+1}</legend><label>Heading<input value="${esc(h)}" maxlength="180" required></label><label>Body text<textarea class="article-text" maxlength="12000" required>${esc(p)}</textarea></label><button type="button" class="admin-button secondary" data-remove="${i}">Remove section</button></fieldset>`).join('')}<button type="button" class="admin-button secondary" data-action="add-section">Add section</button>
 <div class="blog-editor-actions"><button class="admin-button" type="submit">Save draft</button><button class="admin-button secondary" type="button" data-action="preview">Save & preview</button><button class="admin-button" type="button" data-action="publish">${current.status==='published'?'Publish changes':'Publish blog'}</button>${current.status==='published'?'<button class="admin-button danger" type="button" data-action="unpublish">Unpublish</button>':''}</div></form>`;}
 function input(name,label,max,required=false,hint='',readonly=false){return `<label>${label}<input name="${name}" value="${esc(current[name])}" maxlength="${max}" ${required?'required':''} ${readonly?'readonly':''}>${hint?`<small>${hint}</small>`:''}</label>`;}
 function ask(message){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.style.cssText='max-width:460px;padding:28px;border:1px solid #cbd5e1;border-radius:12px;color:#142033';dialog.innerHTML=`<h2>Confirm publication change</h2><p>${esc(message)}</p><div class="blog-editor-actions"><button class="admin-button secondary" data-answer="no">Cancel</button><button class="admin-button" data-answer="yes">Confirm</button></div>`;document.body.append(dialog);const finish=value=>{dialog.close();dialog.remove();resolve(value);};dialog.querySelector('[data-answer="no"]').onclick=()=>finish(false);dialog.querySelector('[data-answer="yes"]').onclick=()=>finish(true);dialog.oncancel=e=>{e.preventDefault();finish(false);};dialog.showModal();});}
 function leave(){return !dirty||confirm('Discard unsaved blog changes?');}
 async function reload(){posts=(await api('/admin/blogs')).posts;}
 async function save(){if(!root.querySelector('form').reportValidity())throw Error('Complete the required fields before saving.');collect();const data=await api('/admin/blogs'+(current.id?'/'+current.id:''),current.id?'PATCH':'POST',current);current=data.post;dirty=false;await reload();render();alert('Draft saved. Publish when you are ready.');}
 async function act(fn){if(busy)return;busy=true;root.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){alert(e.message,true);}finally{busy=false;root.querySelectorAll('button').forEach(b=>b.disabled=false);}}
 const unload=e=>{if(dirty){e.preventDefault();e.returnValue='';}};
 window.addEventListener('beforeunload',unload);
 root.textContent='Loading blogs…';
 (async()=>{try{csrf=(await api('/auth/session')).csrf;await reload();render();}catch(e){if(!disposed)root.textContent=e.message;}})();
 return()=>{disposed=true;window.removeEventListener('beforeunload',unload);};
}
